// The cards over the play area: the title, the pause card and game over. A
// card is lines of text, centered, in a box with an edge; a line can be a
// key (a button on the card, tapped by its id). Drawn on screen changes only.
import { frame, rect, roundRect } from './gfx'
import { drawText, drawTextShadow, textWidth } from './font'
import { L } from './layout'
import { UI } from './palette'

// `block`: lines that go together (the high scores): a heading (`head`) goes when the last line under it does.
export type Line = { text: string; scale?: number; ink?: number; key?: number; optional?: boolean; gap?: number; group?: number;
  block?: number; head?: boolean }

/** `text` in lines no wider than `maxW` at `scale`, broken at spaces: a phrase (two spaces between phrases)
 *  stays whole where it fits, and the lines are as even as their count allows, so no word is left alone. */
function wrapText(text: string, maxW: number, scale: number): string[] {
  const units: string[] = [] // each with the spaces before it
  const phrases = text.split('  ')
  for (let i = 0; i < phrases.length; i++) {
    const words = textWidth(phrases[i], scale) <= maxW ? [phrases[i]] : phrases[i].split(' ')
    for (let j = 0; j < words.length; j++) units.push((j ? ' ' : i ? '  ' : '') + words[j])
  }
  const fill = (w: number) => {
    const out: string[] = []
    let current = ''
    for (const unit of units) {
      if (current && textWidth(current + unit, scale) > w) {
        out.push(current)
        current = unit.trim()
      } else current = current ? current + unit : unit.trim()
    }
    if (current) out.push(current)
    return out
  }
  let best = fill(maxW)
  for (let w = maxW - scale; w > 0; w -= scale) {
    const tried = fill(w)
    if (tried.length !== best.length || tried.some((l) => textWidth(l, scale) > w)) break
    best = tried
  }
  return best
}

// The keys on the card showing: their ids and rectangles, for taps.
const keyIds: number[] = []
const keyRects: number[] = []

/** The card's lines in a box over the play area. Lines marked optional go first when it is too short. */
export function drawCard(cells: Uint8Array, lines: Line[], fullScreen: boolean, within?: { x: number; y: number; w: number; h: number }) {
  const cols = L.cols
  const rows = L.rows
  const ts = L.ts
  const area = within || (fullScreen ? { x: 0, y: 0, w: cols, h: rows } : L.play)
  const pad = (fullScreen ? 6 : 3) * ts
  // A card inside `within` (a field's walls) keeps two cells clear of its edges, its shadow inside them.
  const inset = within ? 2 * ts : 0
  keyIds.length = 0
  keyRects.length = 0
  // Each line's scale, shrunk so it fits the width.
  const maxW = area.w - 2 * inset - 2 * pad - 2
  // Lines too wide even at the smallest scale are wrapped at spaces.
  let shown: Line[] = []
  for (let n = 0; n < lines.length; n++) {
    const line = lines[n]
    if (!line.text || line.key || textWidth(line.text, ts) <= maxW) {
      shown.push(line)
      continue
    }
    for (const text of wrapText(line.text, maxW, ts)) {
      shown.push({ text, ink: line.ink, optional: line.optional, group: n + 1, block: line.block, head: line.head })
    }
  }
  const fitted = (line: Line) => {
    let s = (line.scale || 1) * ts
    while (s > ts && textWidth(line.text, s) + (line.key ? 4 * ts : 0) > maxW) s--
    return s
  }
  // A name over two lines (BLOCK / DROP) keeps one size, the smaller.
  const sizes = new Map<Line, number>()
  for (let i = 0; i < shown.length; i++) {
    const line = shown[i]
    let s = fitted(line)
    const same = (other: Line) => !!other && !other.key && other.scale === line.scale && other.ink === line.ink
    if (!line.key && (line.scale || 1) > 1 && same(shown[i - 1])) {
      s = Math.min(s, sizes.get(shown[i - 1]) as number)
      for (let j = i - 1; j >= 0 && same(shown[j]); j--) sizes.set(shown[j], s)
    }
    sizes.set(line, s)
  }
  const scaleOf = (line: Line) => sizes.get(line) ?? fitted(line)
  const heightOf = (line: Line) => {
    if (!line.text) return (line.gap || 3) * ts
    return 5 * scaleOf(line) + (line.key ? 4 * ts : 0) + 2 * ts
  }
  let total = 0
  for (const line of shown) total += heightOf(line)
  while (total + 2 * pad > area.h - 2 * inset && shown.some((line) => line.optional)) {
    // Drop the last optional line (all of it, when it was wrapped), and a heading left with nothing under it.
    for (let i = shown.length - 1; i >= 0; i--) {
      if (shown[i].optional) {
        const group = shown[i].group
        const block = shown[i].block
        for (let j = i; j >= 0 && (j === i || (group && shown[j].group === group)); j--) {
          total -= heightOf(shown[j])
          shown.splice(j, 1)
        }
        if (block && !shown.some((line) => line.block === block && !line.head)) {
          for (let j = shown.length - 1; j >= 0; j--) {
            if (shown[j].block === block) {
              total -= heightOf(shown[j])
              shown.splice(j, 1)
            }
          }
        }
        break
      }
    }
  }
  let width = 0
  for (const line of shown) {
    const w = textWidth(line.text, scaleOf(line)) + (line.key ? 8 * ts : 0)
    if (w > width) width = w
  }
  const boxW = Math.min(area.w - 2 * Math.max(inset, 1), width + 2 * pad + 2)
  const boxH = Math.min(area.h - 2 * Math.max(inset, 1), total + 2 * pad - 2 * ts)
  const x = area.x + ((area.w - boxW) >> 1)
  const y = area.y + ((area.h - boxH) >> 1)
  if (!fullScreen) {
    rect(cells, cols, rows, x + ts, y + ts, boxW, boxH, UI.CARD_SHADOW)
    rect(cells, cols, rows, x, y, boxW, boxH, UI.CARD)
    frame(cells, cols, rows, x, y, boxW, boxH, UI.CARD_EDGE, ts)
  } else {
    rect(cells, cols, rows, 0, 0, cols, rows, UI.CARD)
  }
  let top = y + pad
  const cx = x + (boxW >> 1)
  for (const line of shown) {
    if (!line.text) {
      top += (line.gap || 3) * ts
      continue
    }
    const s = scaleOf(line)
    const w = textWidth(line.text, s)
    if (line.key) {
      const kw = w + 8 * ts
      const kh = 5 * s + 4 * ts
      roundRect(cells, cols, rows, cx - (kw >> 1), top, kw, kh, UI.CARD_KEY, ts > 1 ? 2 : 1)
      drawText(cells, cols, rows, line.text, cx - (w >> 1), top + 2 * ts, s, UI.CARD_KEY_INK)
      keyIds.push(line.key)
      keyRects.push(cx - (kw >> 1), top, kw, kh)
      top += kh + 2 * ts
      continue
    }
    const ink = line.ink === undefined ? UI.CARD_INK : line.ink
    if (s >= 2 * ts) drawTextShadow(cells, cols, rows, line.text, cx - (w >> 1), top, s, ink, UI.CARD_SHADOW)
    else drawText(cells, cols, rows, line.text, cx - (w >> 1), top, s, ink)
    top += 5 * s + 2 * ts
  }
}

/** The key of the card under cell (x, y), or 0. */
export function cardKeyAt(x: number, y: number): number {
  for (let i = 0; i < keyIds.length; i++) {
    const kx = keyRects[i * 4]
    const ky = keyRects[i * 4 + 1]
    if (x >= kx - 2 && y >= ky - 2 && x < kx + keyRects[i * 4 + 2] + 2 && y < ky + keyRects[i * 4 + 3] + 2) return keyIds[i]
  }
  return 0
}

export function forgetCardKeys() {
  keyIds.length = 0
  keyRects.length = 0
}

/** The high-score lines for a card: the best five, `mark` (a place) shown with arrows. */
export function scoreLines(scores: number[], mark: number): Line[] {
  const lines: Line[] = [{ text: 'HIGH SCORES', ink: UI.CARD_DIM, optional: true, block: 1, head: true }]
  if (!scores.length) lines.push({ text: 'NONE YET', ink: UI.CARD_DIM, optional: true, block: 1 })
  for (let i = 0; i < scores.length; i++) {
    const text = i + 1 + '. ' + pad6(scores[i])
    lines.push({ text: i === mark ? '>' + text + '<' : text, ink: i === mark ? UI.CARD_HI : UI.CARD_INK, optional: true, block: 1 })
  }
  return lines
}

function pad6(n: number): string {
  let s = String(n)
  while (s.length < 6) s = ' ' + s
  return s
}

/** The HUD strip's background, on a screen change. */
export function drawHudBar(cells: Uint8Array) {
  const h = L.hud
  rect(cells, L.cols, L.rows, h.x, h.y, h.w, h.h, UI.HUD_BG)
}

/** The HUD's three places: left, middle and right, each as wide as the widest text it will hold (the
 *  templates given). One that does not fit gets no width and is not drawn. */
export const HUD = { lx: 0, lw: 0, mx: 0, mw: 0, rx: 0, rw: 0, ly: 0, my: 0, ry: 0 }

export function hudSlots(left: string, mid: string, right: string) {
  const h = L.hud
  const ts = L.ts
  HUD.ly = HUD.my = HUD.ry = h.y + 2
  if (L.round) {
    roundSlots(left, mid, right)
    return
  }
  HUD.lx = h.x + 2 * ts
  HUD.lw = textWidth(left, ts)
  HUD.rw = textWidth(right, ts)
  HUD.rx = h.x + h.w - 2 * ts - HUD.rw
  if (HUD.rx < HUD.lx + HUD.lw + 2 * ts) HUD.rw = 0
  const mw = textWidth(mid, ts)
  const from = HUD.lx + HUD.lw + 3 * ts
  const to = HUD.rw ? HUD.rx - 3 * ts : h.x + h.w - 2 * ts
  HUD.mw = mid && to - from >= mw ? mw : 0
  HUD.mx = (from + to - mw) >> 1
}

// On a round panel the HUD is two lines in the arc at the top, each centred:
// the left place on the first (the narrower), the middle and right ones on the second.
function roundSlots(left: string, mid: string, right: string) {
  const h = L.hud
  const ts = L.ts
  const cx = L.cols / 2
  const cy = L.rows / 2
  const inner = Math.min(L.cols, L.rows) / 2 - Math.ceil(12 / L.px)
  const room = (y: number) => 2 * Math.floor(Math.sqrt(Math.max(0, inner * inner - (y - cy) * (y - cy))))
  HUD.ly = h.y + 2
  HUD.my = HUD.ry = h.y + h.h - 5 * ts - 2
  HUD.lw = textWidth(left, ts)
  if (HUD.lw > room(HUD.ly)) HUD.lw = 0
  HUD.lx = Math.round(cx - HUD.lw / 2)
  HUD.mw = mid ? textWidth(mid, ts) : 0
  HUD.rw = right ? textWidth(right, ts) : 0
  const space = room(HUD.my)
  if (HUD.mw + 4 * ts + HUD.rw > space) HUD.rw = 0
  if (HUD.mw > space) HUD.mw = 0
  const both = HUD.mw + (HUD.mw && HUD.rw ? 4 * ts : 0) + HUD.rw
  HUD.mx = Math.round(cx - both / 2)
  HUD.rx = HUD.mx + both - HUD.rw
}

/** One HUD field: `label` dim and `value` bright, in the place at x, `width` cells wide (cleared first);
 *  `right` aligns it to the right of the place; `top` is its line (the HUD's own when not given). Nothing
 *  when the place has no width. */
export function hudField(cells: Uint8Array, x: number, width: number, label: string, value: string, right?: boolean, top?: number) {
  if (width <= 0) return
  const h = L.hud
  const ts = L.ts
  const y = top === undefined ? h.y + 2 : top
  rect(cells, L.cols, L.rows, x, y, width, 5 * ts, UI.HUD_BG)
  const lw = label ? textWidth(label, ts) + 5 * ts : 0
  const at = right ? x + width - lw - textWidth(value, ts) : x
  drawText(cells, L.cols, L.rows, label, at, y, ts, UI.HUD_DIM)
  drawText(cells, L.cols, L.rows, value, at + lw, y, ts, UI.HUD_INK)
}
